#!/usr/bin/env python3
"""Original Greyhaven adventure data; no UO quest prose, cliloc or art identifiers."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
def build():
 def o(id,kind,target,text,n=1):return {'id':id,'kind':kind,'target':target,'text':text,'amount':n}
 def reward(id,n):return {'definition':'greyhaven.item.'+id,'amount':n}
 quests=[
 {'id':'quest.beacon','name':'The Light Below','giver':'npc.sera','recipient':'npc.sera','main':True,'description':'The Broken Beacon once guided Greyhaven ships through the reef. Its lantern heart was taken into the Drowned Cellars. Ask Orrin about the old stonework, follow the north road, and recover the heart from the Lantern Keeper. The upper-vault key and lower-ward lever open the final chamber. Bring its light back to the beacon, then return to me.','completion':'The beacon burns again. Greyhaven names you Lantern Warden; the harbour can face the next dark tide.','fame':450,'karma':250,'objectives':[o('smith','talk','npc.orrin','Ask Orrin about the beacon cellars'),o('beacon','visit','discover.beacon','Follow the north road to the Broken Beacon'),o('upper','visit','cellar1.room1','Enter the upper Drowned Cellars'),o('key','collect','world.item.cellar.key','Carry the Brass Vault Key'),o('lever','object','cellar.lever','Raise the Lower Ward portcullis'),o('keeper','kill','encounter.lower.boss','Defeat the Lantern Keeper'),o('heart','obtain','quest.item.lantern-heart','Recover the Lantern Heart'),o('restore','restore','stairs.beacon','Install the heart at the Broken Beacon')],'rewards':[reward('silver-marks',260),reward('mariner-greatblade',1),reward('healing-tonic',3)]},
 {'id':'quest.morrowwood','name':'The Morrowwood Road','giver':'npc.lena','recipient':'npc.lena','description':'Two tidehounds have claimed the western trail. Defeat the Morrowwood Tidehound and Trail Tidehound, then report to Lena at the east town gate. Clearing them will give the netmakers a safe route through the wood.','completion':'Lena records the cleared trail. The western road belongs to travellers again.','fame':100,'karma':50,'objectives':[o('hound1','kill','encounter.woods.hound1','Defeat the Morrowwood Tidehound'),o('hound2','kill','encounter.woods.hound2','Defeat the Trail Tidehound')],'rewards':[reward('silver-marks',80),reward('healing-tonic',2)]},
 {'id':'quest.forge','name':'A Spark for the Anchor Forge','giver':'npc.orrin','recipient':'npc.orrin','description':'Orrin needs three tide crystals to temper a replacement beacon bracket. Carry them and mark them as quest items before returning. Marked supplies cannot be sold, thrown or dropped until you unmark them or turn them in.','completion':'Orrin fits the new bracket and pays for exactly three crystals. Any extra marked supplies are yours again.','fame':75,'karma':40,'objectives':[o('crystals','obtain','greyhaven.item.tide-crystal','Mark and deliver three carried tide crystals',3)],'rewards':[reward('silver-marks',90),reward('bandage',5)]},
 {'id':'quest.harbour','name':'Letters for the Harbour','giver':'npc.mara','recipient':'npc.cora','description':'Mara has a packet of letters for Cora at Gullhook Docks, south of town. Accept the packet, carry it to Cora, and choose the quest reward when you speak with her. The letters remain physical inventory, including after a death.','completion':'Cora tucks the letters into her coat. News from home is worth more than a fair tide.','fame':50,'karma':40,'objectives':[o('letters','deliver','quest.item.harbour-letter','Carry Mara\'s letters to Cora at the docks')],'rewards':[reward('silver-marks',40)]}
 ]
 people=json.loads((ROOT/'content/original/map.json').read_text())['objects'];by={o['id']:o for o in people}
 routines=[]
 for id,work,social in [('tomas',(111,180),(74,173)),('ada',(77,184),(75,173)),('brin',(116,180),(73,173)),('pella',(67,183),(72,174)),('ivo',(94,182),(74,174)),('fen',(96,228),(76,173)),('maeve',(115,201),(73,174))]:
  npc=by['npc.'+id];routines.append({'npcId':npc['id'],'homeX':npc['x'],'homeY':npc['y'],'workX':work[0],'workY':work[1],'socialX':social[0],'socialY':social[1]})
 trainers=[{'npcId':npc,'skill':skill,'value':1000} for npc,skills in [('npc.orrin',['swords','tactics','anatomy','parry','wrestling','throwing']),('npc.sera',['magery','evalint','meditation','resist']),('npc.elin',['healing'])] for skill in skills]
 out={'quests':quests,'routines':routines,'trainers':trainers};(ROOT/'content/original/adventure.json').write_text(json.dumps(out,indent=2)+'\n');return out
if __name__=='__main__':build();print('Adventure: main quest, three side quests, seven routines and three trainers.')
